insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('81affe36-0f4b-45b7-a9e8-510e27bccda7', '22b56194-abad-4eb3-a2b3-df1755406a57', $$bron 1: Erasmus over de Italiaanse drukker Manutius in Adagia (1500)$$,
   $$geschiedenis-havo-2021-i-ontdekkers-en-hervormers-bron1.png$$,
   $$bron 1 In 1500 publiceert de humanist Erasmus het boek Adagia, een verzameling van Griekse en Romeinse spreuken. Bij de spreuk Festina Lente schrijft hij over de Italiaanse drukker Manutius, die deze spreuk als logo heeft:
Manutius is als het ware geschapen om deze beschaving [van de Oudheid] in haar oude glorie te herstellen; onvermoeibaar zwoegt hij voort. Geen inspanning is hem te zwaar en slechts op dit ene is zijn vurige hoop gericht: de gereedschappen voor de beoefening der schone letteren gezuiverd en gaaf ter hand te stellen aan mannen van goede aanleg (...). [Ik] durf de geleerden te verzekeren dat zij, door het toedoen van deze éne man, binnen weinige jaren zullen beschikken over al de goede auteurs die geschreven hebben in het Latijn en Grieks. En zonder uitzondering van enige tak van wetenschap en dat alles in onverkorte en van fouten gezuiverde vorm. Niemand zal dan ook maar één leemte in zijn bronnenmateriaal hoeven te hebben. Mocht dit ooit lukken, dan zal pas blijken, hoeveel goede handschriften nu nog ontoegankelijk zijn (...). Dan ook zal men merken, hoe ook die teksten, waarvan men nu nog denkt dat die behoorlijk gecorrigeerd zijn, wemelen van de wonderlijkste fouten.$$, 'inline'),
  ('96ff7191-47ba-4920-a227-e0a5438bad8f', '22b56194-abad-4eb3-a2b3-df1755406a57', $$bron 2: sommen uit de rekenmethode De Cijfferinghe van Willem Bartjens (1604)$$,
   $$geschiedenis-havo-2021-i-ontdekkers-en-hervormers-bron2.png$$,
   $$bron 2 In 1604 publiceert de schoolmeester Willem Bartjens een rekenmethode, De Cijfferinghe. Hierin staan sommen als:
1 560 soldaten verdedigen een schans (vestingwerk), en hebben voedsel voor 7 maanden: ze besluiten samen om als ze belegerd worden de schans niet binnen 10 maanden over te geven. Vraag: hoeveel mannen moeten ze laten gaan om met hun voedsel de schans tien maanden te kunnen verdedigen? (oplossing: 168)
2 6 timmermannen maken in 186⅔ dagen een schip van 66 lasten (inhoudsmaat voor schepen). Vraag: als men 10 mannen aanstelt, in hoeveel dagen kunnen die dat schip maken? (oplossing: 112 dagen)$$, 'inline'),
  ('f2ae7359-90f9-414c-9cfa-579902d899c3', '3b6d5808-d8a0-4b21-85ca-c12fb8f348fd', $$bron 4: voorstellen van de commissie-Russell voor een nieuw kiesstelsel (1831)$$,
   $$geschiedenis-havo-2021-i-het-britse-rijk-bron4.png$$,
   $$bron 4 In 1831 presenteert Lord John Russell namens een commissie in het Britse parlement verschillende voorstellen om het Britse kiesstelsel te veranderen:
We stellen voor dat alle kiesdistricten met minder dan 2000 inwoners het recht verliezen om afgevaardigden naar het Parlement te sturen. Dat betekent dat
60 districten verdwijnen, waarmee 119 zetels vrijkomen. Maar we gaan nog verder: er zijn 47 kiesdistricten met minder dan 4000 inwoners. Wij stellen voor dat die districten maximaal één parlementslid kunnen afvaardigen. Het district Weymouth kan daarnaast van 4 naar 2 parlementsleden worden teruggebracht. Dit alles bij elkaar betekent dat er 168 zetels vrijkomen. (…) Wij willen echter niet dat de overgebleven zetels in handen komen van een kleine groep rijken. Daarom stellen we voor dat alle huiseigenaren die jaarlijks minimaal 10 pond aan woonlasten betalen, kiesrecht krijgen1). (…) Dit zijn de mensen die we nodig hebben bij toekomstige uitdagingen voor ons land!
noot 1 Hierdoor komen de zetels terecht bij stedelijke districten.$$, 'inline'),
  ('9fa6f9cb-982a-4376-9633-3e27e327f23e', '3b6d5808-d8a0-4b21-85ca-c12fb8f348fd', $$bron 5: artikel in de Illustrated London News over India (1857)$$,
   $$geschiedenis-havo-2021-i-het-britse-rijk-bron5.png$$,
   $$bron 5 In de Britse krant Illustrated London News staat in 1857 in een artikel over India:
We horen met pijn, maar niet zozeer met afkeer, van de dood van onze dappere officieren en soldaten die werden afgeslacht, want het hoort bij de taak van een soldaat om de dood tegemoet te treden. Maar als we lezen over de gruwelijkheden die zijn begaan tegen onze vrouwen en kinderen, dan wordt het hart van Engeland geraakt; en het verdriet om hun lot, hoe groot dat ook is, wordt overschaduwd door de afschuw die we voelen voor hun onmenselijke moordenaars en de grimmige overtuiging dat zij moeten worden getroffen door volledige en onwrikbare gerechtigheid.$$, 'inline'),
  ('05a95d1d-61eb-46b1-8c29-67f3cd37efaf', '3b6d5808-d8a0-4b21-85ca-c12fb8f348fd', $$bron 6: schilderij The Secret of England's Greatness van Thomas Jones Barker (1863)$$,
   $$geschiedenis-havo-2021-i-het-britse-rijk-bron6.png$$,
   $$bron 6 De Britse schilder Thomas Jones Barker maakt in 1863 het schilderij The Secret of England''s Greatness (Het geheim van Engelands grootheid):
[Afbeelding] Schilderij: koningin Victoria staat in een paleiszaal en overhandigt een bijbel aan een geknielde Afrikaanse vorst; achter haar staan enkele Britse heren.
Toelichting Op de voorgrond staat de Britse koningin Victoria, die een bijbel overhandigt aan een vorst uit oostelijk Afrika.$$, 'inline'),
  ('af833821-8ca4-4b5f-bf1e-028d8152a1fb', 'f28a4cbe-757a-41c5-a88d-1add732e6a09', $$bron 3: brief van arts Jacobus Reichard vanaf plantage Vreedestein in Demerary (1781)$$,
   $$geschiedenis-havo-2021-i-pruiken-en-revoluties-bron3.png$$,
   $$bron 3 In 1781 schrijft de arts Jacobus Reichard een brief vanuit de suikerplantage Vreedestein in de Nederlandse kolonie Demerary (in Zuid-Amerika) aan zijn werkgever in Amsterdam:
De hemel zij dank: Wij zijn na een voorspoedige en gezegende reis op uw plantage Vreedestein aangekomen. (...) Ik zal deze maand op de plantage gaan wonen zodra de apotheek en de woning klaar zijn. Op uw plantage zijn feitelijk geen zieken, op vier negers na die aan de jas of zogenaamde Indiaanse pokken1) lijden. En Quacu, de suikerkoker, die veertien dagen kwakkelde door de beliac2), is hersteld. Een meid, Henrietta, is bevallen van een mulat3). Zij heeft de bevalling overleefd maar het kind is overleden. Ik heb de medicijnen gecontroleerd maar die zijn niet in goede staat zoals de bijgevoegde monsters laten zien. Ik heb gevraagd om extra medicijnen maar slechts een klein gedeelte ontvangen. Wilt u mij de gevraagde medicijnen alsnog opsturen zodat ik er straks geen tekort aan heb?
noot 1 Jas of Indiaanse pokken is een huidziekte.
noot 2 Beliac is een vorm van loodvergiftiging. noot 3 Een mulat is iemand die een witte en een gekleurde ouder heeft.$$, 'inline'),
  ('dadddf53-19d5-4fc6-a6e3-f9f895db1aa0', '1835142f-060c-4ffc-8f82-ecb8aacae0fd', $$bron 10: verslag van voorlichter Willem Brandt over Nederlandse militairen in Indonesië (1947)$$,
   $$geschiedenis-havo-2021-i-tijd-van-wereldoorlogen-bron10.png$$,
   $$bron 10 De Nederlandse regering zendt troepen naar de kolonie Nederlands-Indië om daar na het einde van de Japanse bezetting de macht terug te krijgen. Willem Brandt, een voorlichter in dienst van het Koninklijk Nederlands-Indische Leger, schrijft in 1947:
De gevangenen die ons in handen vallen en die men nieuwsgierig beziet en uithoort zijn bezield met de meest fantastische opvattingen over de Nederlandse bedoelingen en methoden. Het zijn meestal jongens nog, opgevoed in blankenhaat, onder een Japans beheer, getraind in het wapengeweld door Japanse deserteurs in het binnenland. Jongens vaak, die niet weten wat zij doen. (…) Dat zijn zij: de losgebroken horden, het schuim van het Indonesisch volk, de op drift geraakte bandeloze legers van een machteloze leiding, die de toegestoken hand van hulp en steun uit dom wanbegrip geweigerd heeft, gedreven door wilde fanatici, profiteurs en bekrompen partijbonzen.$$, 'inline'),
  ('2f298cb4-dcc3-464d-8454-3db8db5d7406', '041c3070-d0dd-480e-bece-1e5dbcb77a2a', $$bron 7: bericht van generaal Wilhelm Groener aan de Duitse regering (november 1918)$$,
   $$geschiedenis-havo-2021-i-duitsland-in-europa-bron7.png$$,
   $$bron 7 In november 1918 stuurt de Duitse generaal Wilhelm Groener een bericht aan de Duitse regering:
Veldmaarschalk Von Hindenburg heeft zich bereid verklaard aan te willen blijven als hoogste legeraanvoerder, totdat het leger stabiel en in alle orde zal zijn teruggeleid naar het vaderland. Hij heeft de commandoleiding en de officieren verzocht om hun plicht onverminderd te blijven doen. De veldmaarschalk verwacht van de nieuwe regering, dat zij de zorg voor het leger met alle middelen veiligstelt en hiervoor elke mogelijke verstoring van het treinverkeer zal verhinderen.$$, 'inline'),
  ('4c826f5e-0bac-4d58-8fec-64c0eda1ef7a', '041c3070-d0dd-480e-bece-1e5dbcb77a2a', $$bron 8: Robert Boothby in het Britse parlement over het beleid ten aanzien van Duitsland (1938)$$,
   $$geschiedenis-havo-2021-i-duitsland-in-europa-bron8.png$$,
   $$bron 8 Op 22 februari 1938 vindt in het Britse parlement een debat plaats over het beleid ten aanzien van Duitsland. Het parlementslid Robert Boothby zegt tijdens dit debat:
Achteraf gezien denk ik dat het Verdrag van Versailles toch niet het wondermiddel voor het bereiken van vrede was waarvoor de onderhandelaars het destijds hielden. Ik durf zelfs te beweren dat het verdrag veel van onze huidige problemen heeft veroorzaakt (…). Ik zal de schuld hiervoor niet neerleggen bij Mr. Lloyd George1), want de obstakels waren toen bijna onoverkomelijk en hij stond onder enorme druk van de publieke opinie in dit land, die zakelijk en rustig onderhandelen bijna onmogelijk maakte. Dat er uiteindelijk toch een verdrag kwam, is op zich al verbazingwekkend. Maar dat neemt niet weg dat het geen goed verdrag was. Dit zullen we moeten meewegen bij het beoordelen van de situatie waarin we ons nu bevinden.
noot 1 Minister-president Lloyd George onderhandelde in 1919 namens Groot-Brittannië over het Verdrag van Versailles.$$, 'inline'),
  ('79dd2f23-687f-4a8d-b1c8-da22402d14e7', '041c3070-d0dd-480e-bece-1e5dbcb77a2a', $$bron 9: foto van Duitse burgers die de Elbe oversteken (1 mei 1945)$$,
   $$geschiedenis-havo-2021-i-duitsland-in-europa-bron9.png$$,
   $$bron 9 Foto van Duitse burgers die op 1 mei 1945 de rivier de Elbe oversteken om de naderende Sovjettroepen voor te blijven:
[Afbeelding] Foto: Duitse burgers met koffers en tassen klimmen over de verwrongen ijzeren balken van een verwoeste brug over de Elbe.$$, 'inline'),
  ('ccbf324e-8191-4999-8d4d-4ce98c85165a', '041c3070-d0dd-480e-bece-1e5dbcb77a2a', $$bron 11: De Waarheid over de opstand in Oost-Berlijn (17 juni 1953)$$,
   $$geschiedenis-havo-2021-i-duitsland-in-europa-bron11.png$$,
   $$bron 11 In 1953 komen Oost-Duitse arbeiders in opstand tegen de regering. In het communistische Nederlandse dagblad De Waarheid van 17 juni 1953 staat over het uitbreken van die opstand een artikel:
Onze correspondent telefoneerde ons gisteravond dat de aanleiding van de demonstraties (…) van Oost-Duitse bouwvakarbeiders een onjuist toegepaste regeringsmaatregel over de verhoging van de arbeidsnormen is geweest. De spionage- en sabotage-organisaties in het Westen hadden hiervan gebruik gemaakt om enkele groepen arbeiders tot demonstraties aan te zetten, die onmiddellijk aangevuld werden door mannen uit West-Berlijn. Toen de arbeiders voor het regeringsgebouw van het ministerie van Wederopbouw verschenen, werden zij door [de DDR] minister Selbmann toegesproken. Deze vertelde hun dat de regering al besloten had om de onjuiste maatregelen in te trekken. Agenten uit West-Berlijn probeerden de arbeiders over te halen om naar het Westen te marcheren "om daar hun recht te zoeken". Dit provocerende voorstel werd onmiddellijk afgewezen met de verklaring: "Als wij klachten hebben, dan spreken wij onze eigen regering daarop aan." De arbeiders gingen na de mededeling van minister Selbmann gerustgesteld weer naar hun werk.$$, 'inline'),
  ('b936413c-bb42-4d4b-99a2-9361ff344980', '03a02853-4a73-4e4c-bf3b-854db1b33ec3', $$bron 12: lied Regering (krijg de tering) van punkband B.G.K. (1983)$$,
   $$geschiedenis-havo-2021-i-nederland-1948-2008-bron12.png$$,
   $$bron 12 Uit het lied Regering (krijg de tering) van de Nederlandse punkband Balthasar Gerards Kommando (B.G.K.) uit 1983:
Grote kampanjes1) veel beloven Moeten wij die lulkoek geloven Stemmen helpt allang niet meer Rechts wint toch wel keer op keer Je wordt verwacht je neer te leggen Bij wat de meeste mensen zeggen Als je ertegen protesteert Word je met harde hand bekeerd
noot 1 Verkiezingscampagnes$$, 'inline'),
  ('51f1fc56-f3b6-499d-8436-116e48c4f682', 'c42f51e6-88e1-4883-959c-f5f58b3f67f0', $$bron 13: cartoon van Carlo Schneider over de Europese politiek (2005)$$,
   $$geschiedenis-havo-2021-i-computer-en-televisie-bron13.png$$,
   $$bron 13 Cartoon van de Luxemburgse tekenaar Carlo Schneider uit 2005:
[Afbeelding] Cartoon: twee politici dragen een spandoek met ''Europapolitik''; een man links met een tas met ''Non'' geeft een van hen een trap, een vrouw rechtsachter doet hetzelfde bij de ander.
Toelichting De mannen die het spandoek met de tekst ''Europapolitiek'' erop vasthouden zijn de Franse president Chirac en de Nederlandse premier Balkenende. De man links stelt het Franse volk voor, op zijn tas staat Non (Nee). De vrouw rechtsachter stelt het Nederlandse volk voor.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('ed91ae6d-0e2d-4835-992e-e27a4847396a', '777d2587-3a1a-4b23-a6b7-c2607f90cde4', 1,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["chronologie", "Opstand", "Jamestown", "imperialisme", "DDR", "Tweede Wereldoorlog"]'::jsonb,
   $$Chronologisch ordenen van zes vernoemingen van steden naar personen uit verschillende tijdvakken.$$,
   $$geschiedenis-havo-2021-i-door-de-tijd-heen-vraag1.png$$, $$Steden worden soms vernoemd naar personen. De volgende vernoemingen staan in willekeurige volgorde:
1 De Amerikaanse hoofdstad Washington werd vernoemd naar George Washington, de eerste president van de Verenigde Staten, nadat hij de locatie van deze federale hoofdstad had uitgekozen.
2 De Brabantse vesting Willemstad werd vernoemd naar Willem van Oranje, de eerste leider van de Nederlandse Opstand, die kort daarvoor in Delft was vermoord.
3 De havenstad Lüderitz, in de kolonie Duits-Zuidwest-Afrika, werd vernoemd naar de koopman Adolf Lüderitz, die verdronk tijdens zijn zoektocht naar grondstoffen voor de Duitse industrie.
4 De regering van de DDR noemde een stad die werd aangelegd voor grootschalige ijzer- en staalproductie Stalinstadt, naar de pas overleden Sovjetleider Jozef Stalin.
5 In de Engelse kolonie Virginia werd de stad Jamestown bij de stichting vernoemd naar koning James I, die aan kolonisten toestemming gaf in Amerika tabak te produceren voor de Engelse markt.
6 Na de Duitse inval werd voorgesteld de Poolse stad Zamość Himmlerstadt te noemen, naar de nationaalsocialistische SS-leider Heinrich Himmler. 2p 1 Zet deze beschrijvingen in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('46b61335-76c0-42f7-b0ec-6687a351a7c7', '777d2587-3a1a-4b23-a6b7-c2607f90cde4', 8,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}, {"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["chronologie", "reformatie", "Republiek", "Bataafse revolutie", "economische wereldcrisis", "wederopbouw"]'::jsonb,
   $$Chronologisch ordenen van zes gebeurtenissen rond glas-in-loodramen in Nederland.$$,
   $$geschiedenis-havo-2021-i-door-de-tijd-heen-vraag8.png$$, $$De volgende gebeurtenissen rondom glas-in-loodramen in Nederland staan in willekeurige volgorde:
1 Door de emancipatie van katholieken in Nederland en het daarbij horende herstel van de bisdommen groeide de productie van gebrandschilderde kerkramen.
2 Er ontstond een nieuwe belangstelling voor glas-in-loodkunst tijdens de wederopbouw, doordat werd bepaald dat 1,5% van de bouwsom van overheidsgebouwen moest worden besteed aan kunst.
3 In de Republiek werden in opdracht van rijke regenten gebrandschilderde medaillons in grachtenpanden geplaatst.
4 Patriotten vernielden tijdens de Bataafse revolutie, een democratische revolutie, glas-in-loodramen waarop wapenschilden van voorname families waren afgebeeld.
5 Tijdens de economische wereldcrisis moest er goedkoop worden gebouwd, waardoor de vraag naar decoratieve glas-in-loodramen sterk terugliep.
6 Veel glas-in-loodramen in kerken en kloosters gingen verloren tijdens de reformatie. 2p 8 Zet deze gebeurtenissen in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('b0f6d1ec-7021-4baf-a6a6-8ef9489cadd5', '22b56194-abad-4eb3-a2b3-df1755406a57', 2,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}]'::jsonb,
   '["humanisme", "renaissance", "klassieke Oudheid", "boekdrukkunst", "Erasmus", "kenmerkend aspect"]'::jsonb,
   $$Met twee kenmerkende aspecten van de zestiende eeuw het positieve oordeel van Erasmus over drukker Manutius verklaren.$$,
   $$geschiedenis-havo-2021-i-ontdekkers-en-hervormers-vraag2.png$$, $$Gebruik bron 1. Erasmus geeft een positief oordeel over het werk van Manutius. Dit positieve oordeel kun je verklaren met twee kenmerkende aspecten van de zestiende eeuw. 4p 2 Noem deze twee verschillende kenmerkende aspecten uit de zestiende eeuw en verklaar daarmee telkens een positief oordeel van Erasmus.$$, array['81affe36-0f4b-45b7-a9e8-510e27bccda7']::uuid[]),
  ('b73c95a3-38d8-413b-8a99-f393d6efc960', '22b56194-abad-4eb3-a2b3-df1755406a57', 3,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["reformatie", "Luther", "katholieke kerk", "boekdrukkunst", "volkstaal", "verklaren"]'::jsonb,
   $$Verklaren waarom een katholieke hertog drukkers verbood godsdienstige geschriften in het Duits te drukken.$$,
   $$geschiedenis-havo-2021-i-ontdekkers-en-hervormers-vraag3.png$$, $$Een anekdote: In 1524 klaagden de bestuurders van de Duitse stad Leipzig bij de katholieke hertog George van Saksen over zijn gebod dat de drukkers in Leipzig alleen maar godsdienstige geschriften in het Latijn mochten drukken (waar volgens hen geen vraag naar was) en niet in het Duits (waar veel vraag naar was). 2p 3 Verklaar het gebod van George van Saksen door aan te geven:
− wat de hertog wilde bereiken op godsdienstig gebied en
− dat juist dit gebod hieraan kon bijdragen.$$, array[]::uuid[]),
  ('affae6fd-7b4b-4f74-b978-9d3b485f97d1', '22b56194-abad-4eb3-a2b3-df1755406a57', 4,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}]'::jsonb,
   '["Opstand", "Tachtigjarige Oorlog", "Republiek", "Gouden Eeuw", "handel", "kenmerkend aspect"]'::jsonb,
   $$Met kenmerkende aspecten uitleggen bij welke actualiteit in de zestiende en zeventiende eeuw de sommen van Bartjens aansluiten.$$,
   $$geschiedenis-havo-2021-i-ontdekkers-en-hervormers-vraag4.png$$, $$Gebruik bron 2. Bartjens sluit met zijn sommen aan op de actuele situatie in de Republiek in de zestiende én de zeventiende eeuw. 4p 4 Leg voor beide sommen apart uit welke actualiteit dit is, waarbij je je antwoord voor de eerste som ondersteunt met een kenmerkend aspect uit de zestiende eeuw en voor de tweede som met een kenmerkend aspect uit de zeventiende eeuw.$$, array['96ff7191-47ba-4920-a227-e0a5438bad8f']::uuid[]),
  ('27e829a4-793f-479b-8a42-81b642742c08', '3b6d5808-d8a0-4b21-85ca-c12fb8f348fd', 9,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["Reform Bill", "industriële revolutie", "democratisering", "kiesrecht", "Groot-Brittannië", "bron onderbouwen"]'::jsonb,
   $$Met de voorstellen van een commissie uit 1831 aantonen dat de Britse samenleving door de industriële revolutie veranderde en democratiseerde.$$,
   $$geschiedenis-havo-2021-i-het-britse-rijk-vraag9.png$$, $$Gebruik bron 4. Twee beweringen over de voorstellen van de commissie:
1 Uit de voorstellen blijkt dat de Britse samenleving door de industriële revolutie is veranderd.
2 De voorstellen dragen bij aan de democratisering van Groot-Brittannië. 2p 9 Ondersteun beide beweringen, waarbij je telkens aangeeft welk voorstel van de commissie erbij past.$$, array['f2ae7359-90f9-414c-9cfa-579902d899c3']::uuid[]),
  ('4e7d5f4b-9875-436d-b2a2-4c6d6f69aa8b', '3b6d5808-d8a0-4b21-85ca-c12fb8f348fd', 10,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["Reform Bill", "1832", "industriële ondernemers", "kiesrecht", "liberalisme", "democratisering"]'::jsonb,
   $$De kieswet van 1832 noemen en uitleggen waarom die gunstig was voor industriële ondernemers.$$,
   $$geschiedenis-havo-2021-i-het-britse-rijk-vraag10.png$$, $$De plannen van de commissie in 1831 (zie bron 4) werden uiteindelijk doorgevoerd in een wet in 1832. 2p 10 Noem deze wet en geef aan waardoor de wet gunstig was voor de industriële ondernemers.$$, array['f2ae7359-90f9-414c-9cfa-579902d899c3']::uuid[]),
  ('e43c8133-8ed3-48d8-8586-cf41e5d4b293', '3b6d5808-d8a0-4b21-85ca-c12fb8f348fd', 11,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["Opstand van 1857", "direct gezag", "East India Company", "Britse pers", "beeldvorming", "propaganda"]'::jsonb,
   $$Uitleggen hoe een Brits krantenartikel uit 1857 de overgang naar direct Brits gezag in India ondersteunde.$$,
   $$geschiedenis-havo-2021-i-het-britse-rijk-vraag11.png$$, $$Gebruik bron 5. Met artikelen als deze wordt een verandering in het Britse bestuur in India ondersteund. 4p 11 Licht dit toe door:
− de gebeurtenis te noemen waar dit artikel verslag van doet en
− zonder bron aan te geven welke Britse beleidsverandering hierna wordt ingevoerd en
− uit te leggen dat dit artikel die beleidsverandering wil ondersteunen.$$, array['9fa6f9cb-982a-4376-9633-3e27e327f23e']::uuid[]),
  ('45aa10c8-f280-43de-8a45-dd3ce0b93028', '3b6d5808-d8a0-4b21-85ca-c12fb8f348fd', 12,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["imperialisme", "superioriteitsgevoel", "beschavingsmissie", "christendom", "koningin Victoria", "bron analyseren"]'::jsonb,
   $$Met verwijzingen naar een schilderij uit 1863 aantonen hoe het Britse imperialisme werd onderbouwd.$$,
   $$geschiedenis-havo-2021-i-het-britse-rijk-vraag12.png$$, $$Gebruik bron 6. Jones Barker onderbouwt met dit schilderij het Britse imperialisme. 4p 12 Toon dit aan door twee voorbeelden van onderbouwing te noemen die Jones Barker weergeeft, waarbij je je antwoord ondersteunt met telkens een verschillende verwijzing naar de bron.$$, array['05a95d1d-61eb-46b1-8c29-67f3cd37efaf']::uuid[]),
  ('6e9573d6-1578-44f7-bf6d-33f6b319ab50', '3b6d5808-d8a0-4b21-85ca-c12fb8f348fd', 13,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["Swadeshi-beweging", "afzetmarkt", "huisnijverheid", "Indiaas nationalisme", "katoenindustrie", "economische verklaring"]'::jsonb,
   $$Economisch verklaren waarom de Swadeshi-beweging ontstond en waarom Britse kranten er economisch en politiek negatief over waren.$$,
   $$geschiedenis-havo-2021-i-het-britse-rijk-vraag13.png$$, $$Twee gegevens over de Swadeshi-beweging in India:
1 In 1905 namen de oprichters van de Swadeshi-beweging voor het stadhuis van Calcutta een resolutie aan in het bijzijn van 20.000 Indiërs, waarin ze Indiërs opriepen hun eigen kleding te weven en te produceren.
2 In Groot-Brittannië publiceerden kranten artikelen waarin de Swadeshi-beweging werd beschreven als gevaarlijk en onwenselijk. 3p 13 Licht beide gegevens toe door:
− een economische verklaring te geven voor het ontstaan van de Swadeshi-beweging en
− een economische en een politieke verklaring te geven voor de reactie van de Britse kranten.$$, array[]::uuid[]),
  ('052c7bcc-e05a-47ee-9d19-d37f34eb8fae', 'f28a4cbe-757a-41c5-a88d-1add732e6a09', 7,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["plantagekoloniën", "slavernij", "abolitionisme", "Suriname", "bruikbaarheid", "onderzoeksvraag"]'::jsonb,
   $$Uitleggen welk deel van een onderzoek naar plantagekoloniën en abolitionisme je met een brief van een plantagearts wel en niet kunt illustreren.$$,
   $$geschiedenis-havo-2021-i-pruiken-en-revoluties-vraag7.png$$, $$Gebruik bron 3. Stel: je doet onderzoek naar ''de uitbouw van de Europese overheersing, met name in de vorm van plantagekoloniën, en de opkomst van het abolitionisme''. Je concludeert dat je met de taak van Reichard een onderdeel van je onderzoek wél kunt illustreren en een ander onderdeel niet. 4p 7 Leg beide delen van je conclusie uit.$$, array['af833821-8ca4-4b5f-bf1e-028d8152a1fb']::uuid[]),
  ('8dedb168-1a57-48fb-8bc4-871adef2a48b', '1835142f-060c-4ffc-8f82-ecb8aacae0fd', 18,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Wereldoorlogen — overig (1900-1950)"}]'::jsonb,
   '["dekolonisatie", "Indonesië", "politionele acties", "eenzijdigheid", "nationalisme", "kenmerkend aspect"]'::jsonb,
   $$Uitleggen waarom een Nederlands verslag over het militaire ingrijpen in Indonesië eenzijdig is en dat ingrijpen verklaren met een kenmerkend aspect.$$,
   $$geschiedenis-havo-2021-i-tijd-van-wereldoorlogen-vraag18.png$$, $$Gebruik bron 10 Stel: je doet onderzoek naar het Nederlandse ingrijpen in Nederlands-Indië en je vindt deze bron. Je concludeert dat dit verslag een eenzijdige weergave is. 3p 18 Licht je conclusie toe door:
− uit te leggen welke boodschap Brandt wil overbrengen over het Nederlandse ingrijpen, waarbij je je antwoord ondersteunt met een verwijzing naar de bron en
− zonder bron met een kenmerkend aspect uit de twintigste eeuw een verklaring te geven voor het Nederlandse ingrijpen.$$, array['dadddf53-19d5-4fc6-a6e3-f9f895db1aa0']::uuid[]),
  ('278fabb1-3d99-40d3-8dfe-f3b8fe90ca37', '041c3070-d0dd-480e-bece-1e5dbcb77a2a', 14,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["Republiek van Weimar", "dolkstootlegende", "wapenstilstand", "legerleiding", "conservatieve elite", "parlementaire democratie"]'::jsonb,
   $$Uitleggen welke politieke verandering de Duitse legerleiding in 1918 mogelijk maakte en welke kritiek op Weimar de elite met dit bericht kon onderbouwen.$$,
   $$geschiedenis-havo-2021-i-duitsland-in-europa-vraag14.png$$, $$Gebruik bron 7. Dit bericht wordt gezien als een belangrijk document in de ontstaansgeschiedenis van de Republiek van Weimar. 3p 14 Licht deze visie toe door:
− aan te geven welke politieke verandering in Duitsland in 1918 de legerleiding met deze reactie mogelijk maakt en
− uit te leggen welke kritiek op de regering van de Republiek van Weimar de conservatieve elite met dit bericht kan onderbouwen.$$, array['2f298cb4-dcc3-464d-8454-3db8db5d7406']::uuid[]),
  ('b62aaa70-6fa3-495a-903b-2b69bba2783a', '041c3070-d0dd-480e-bece-1e5dbcb77a2a', 15,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["totalitarisme", "Volksgemeinschaft", "nationaalsocialisme", "terreur", "Hitlergroet", "argumenteren"]'::jsonb,
   $$Met een anekdote over een gevangene ondersteunen dat nazi-Duitsland een totalitaire staat was en een Volksgemeinschaft creëerde.$$,
   $$geschiedenis-havo-2021-i-duitsland-in-europa-vraag15.png$$, $$Een Duitse gevangene schreef over een medegevangene eind jaren 1930: "''Wees verstandig'' zeiden zijn vrienden. ''Wat geeft het nu om af en toe ''Heil Hitler'' te zeggen. Doe zoals wij. Wij menen het toch ook niet''. Hij schudde zijn hoofd. De volgende dag weigerde hij weer. Hij ging de donkere cel in. Veertien dagen." Uit de behandeling van de gevangene blijkt dat:
1 Duitsland eind jaren 1930 een totalitaire staat was geworden en
2 er een Volksgemeinschaft werd gecreëerd in Duitsland. 2p 15 Ondersteun beide beweringen, elk met een verschillend argument.$$, array[]::uuid[]),
  ('b5b0caab-0dca-44cf-b07f-8d7f707b68a7', '041c3070-d0dd-480e-bece-1e5dbcb77a2a', 16,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["Verdrag van Versailles", "appeasementpolitiek", "Conferentie van München", "continuïteit en verandering", "Brits beleid", "bron analyseren"]'::jsonb,
   $$Continuïteit en verandering in het Britse beleid tegenover Duitsland in 1919 en 1938 aantonen met een parlementaire toespraak.$$,
   $$geschiedenis-havo-2021-i-duitsland-in-europa-vraag16.png$$, $$Gebruik bron 8. Een interpretatie: Boothby ziet continuïteit en verandering in het beleid dat de Britse regering in 1919 en in 1938 voert ten aanzien van Duitsland. 3p 16 Onderbouw deze interpretatie door:
− zonder bron aan te geven welk zelfde doel de Britse regering in 1919 en in 1938 probeert te bereiken met haar beleid en
− uit te leggen op welke verandering in het Britse beleid in 1938 Boothby reageert, waarbij je je antwoord ondersteunt met een passende verwijzing naar de bron.$$, array['4c826f5e-0bac-4d58-8fec-64c0eda1ef7a']::uuid[]),
  ('30cf828d-8c20-4fa9-bb87-395892b29eab', '041c3070-d0dd-480e-bece-1e5dbcb77a2a', 17,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["capitulatie", "ontwrichting", "Heimatvertriebene", "Sovjettroepen", "1945", "foto als bron"]'::jsonb,
   $$Met een foto uit mei 1945 de economische en sociale ontwrichting van Duitsland illustreren.$$,
   $$geschiedenis-havo-2021-i-duitsland-in-europa-vraag17.png$$, $$Gebruik bron 9. Met deze foto kun je de economische en de sociale ontwrichting van de Duitse samenleving in mei 1945 illustreren. 2p 17 Toon beide aan.$$, array['79dd2f23-687f-4a8d-b1c8-da22402d14e7']::uuid[]),
  ('c2397ae1-21d6-48b9-b067-b3fe2b55129a', '041c3070-d0dd-480e-bece-1e5dbcb77a2a', 19,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["oorzaak en gevolg", "Blokkade van Berlijn", "Ostpolitik", "Brezjnevdoctrine", "Duitse hereniging", "euro"]'::jsonb,
   $$Vier gebeurtenissen uit de Duitse geschiedenis na 1945 koppelen aan hun gevolgen.$$,
   $$geschiedenis-havo-2021-i-duitsland-in-europa-vraag19.png$$, $$Hieronder staan in de linkerkolom vier gebeurtenissen uit de Duitse geschiedenis (a tot en met d) in chronologische volgorde en in de rechterkolom vijf gevolgen (1 tot en met 5) in willekeurige volgorde:
Gebeurtenissen: Gevolgen: a Jozef Stalin liet de 1 De Verenigde Staten stelden een toegangswegen naar West- luchtbrug in. Berlijn blokkeren. 2 Frankrijk steunde openlijk de Duitse plannen voor hereniging. b Willy Brandt startte met de 3 Oost-Duitse arbeiders startten met uitvoering van de Ostpolitik. de bouw van de Muur in Berlijn.
4 Oost-Duitse burgers trokken via c Michael Gorbatsjov besloot de Hongarije naar het Westen, nadat de Brezjnevdoctrine los te laten. grens met Oostenrijk was opengesteld. d Helmut Kohl kondigde aan de 5 West-Duitsland en Oost- Duitsland Duitse mark te vervangen door erkenden elkaar als gelijkwaardige de euro. staten.
2p 19 Geef voor elke gebeurtenis aan welk gevolg daarbij hoort. Noteer alleen de letter en het daarbij behorende cijfer. Let op: er blijft één gevolg over.$$, array[]::uuid[]),
  ('b05d80d3-0c51-4f2a-a5d9-ae5332bd9536', '041c3070-d0dd-480e-bece-1e5dbcb77a2a', 21,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["DDR", "opstand 1953", "communisme", "planeconomie", "economische malaise", "standplaatsgebondenheid"]'::jsonb,
   $$Uitleggen welk communistisch standpunt De Waarheid over de Oost-Duitse opstand van 1953 geeft en een oorzaak van de Oost-Duitse malaise noemen.$$,
   $$geschiedenis-havo-2021-i-duitsland-in-europa-vraag21.png$$, $$Gebruik bron 11. Een conclusie: De redactie van De Waarheid geeft een communistisch standpunt weer over de opstand. 3p 21 Ondersteun deze conclusie door:
− uit te leggen welk communistisch standpunt De Waarheid over de opstand weergeeft, waarbij je je antwoord ondersteunt met een verwijzing naar de bron en
− zonder bron een oorzaak voor de economische malaise te noemen waarin de DDR zich in 1953 bevindt.$$, array['ccbf324e-8191-4999-8d4d-4ce98c85165a']::uuid[]),
  ('dcb7af3b-6dac-4a70-ad9d-6bed3bc2f35d', '041c3070-d0dd-480e-bece-1e5dbcb77a2a', 22,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["Staatssicherheitsdienst", "DDR", "opstand 1953", "nuanceren", "totalitaire dictatuur", "beeldvorming"]'::jsonb,
   $$Uitleggen hoe de uitbreiding van de Stasi na 1953 het beeld van de Oost-Duitse arbeiders in de bron nuanceert.$$,
   $$geschiedenis-havo-2021-i-duitsland-in-europa-vraag22.png$$, $$Gebruik bron 11. Een gegeven: Na het neerslaan van de opstand worden de bevoegdheden van de Staatssicherheitsdienst in de DDR uitgebreid. 2p 22 Leg uit dat dit gegeven het beeld van de Oost-Duitse arbeiders, zoals dat wordt geschetst in de bron, nuanceert.$$, array['ccbf324e-8191-4999-8d4d-4ce98c85165a']::uuid[]),
  ('77514b91-c05e-4df6-a08e-1a81923684ef', '041c3070-d0dd-480e-bece-1e5dbcb77a2a', 23,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["BRD", "DDR", "Duitse deling", "erkenning", "Koude Oorlog", "Adenauer"]'::jsonb,
   $$Uitleggen dat een West-Duitse boycot van een ijshockeywedstrijd tegen de DDR in 1961 paste bij de opstelling van de BRD.$$,
   $$geschiedenis-havo-2021-i-duitsland-in-europa-vraag23.png$$, $$Tijdens het wereldkampioenschap ijshockey in 1961 verbood de leiding van de West-Duitse ijshockeybond hun spelers deel te nemen aan een wedstrijd tegen het team van de DDR. De West-Duitse spelers zouden, als ze de wedstrijd verloren, aanwezig moeten zijn bij het hijsen van de Oost-Duitse vlag en het spelen van het Oost-Duitse volkslied. 2p 23 Leg uit dat dit besluit paste bij de opstelling van de BRD ten aanzien van de DDR op dat moment.$$, array[]::uuid[]),
  ('72d17de4-3b97-4116-b7c7-1646e0547d91', '03a02853-4a73-4e4c-bf3b-854db1b33ec3', 20,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["NAVO", "neutraliteitspolitiek", "Koude Oorlog", "Marshallhulp", "westers bondgenootschap", "politieke verklaring"]'::jsonb,
   $$Uitleggen bij welke verandering in de Nederlandse buitenlandse politiek het NAVO-lidmaatschap paste en die verandering politiek verklaren.$$,
   $$geschiedenis-havo-2021-i-nederland-1948-2008-vraag20.png$$, $$In 1949 was Nederland een van de oprichters van de NAVO. 3p 20 Leg uit bij welke verandering van de Nederlandse buitenlandse politiek na 1945 het lidmaatschap van de NAVO paste en geef vervolgens een politieke verklaring voor deze verandering.$$, array[]::uuid[]),
  ('7fa0c5ee-a80b-4d76-a26d-4f305f957bb2', '03a02853-4a73-4e4c-bf3b-854db1b33ec3', 24,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["oliecrisis", "1973", "energiebesparing", "economische crisis", "overheidsvoorlichting", "context"]'::jsonb,
   $$Uitleggen dat een overheidsbericht over zuinig rijden paste bij de oliecrisis van 1973.$$,
   $$geschiedenis-havo-2021-i-nederland-1948-2008-vraag24.png$$, $$Een anekdote: In 1973 werd in overleg met het ministerie van Economische Zaken het volgende bericht in de landelijke dagbladen geplaatst: "Als u wat kalmer optrekt en rustiger rijdt, bespaart u per dag 1.300.000 liter benzine. In een test is gebleken dat onrustig ruw rijden ten koste gaat van indrukwekkende hoeveelheden brandstof. Wegspuiten bij een stoplicht en hard remmen op het laatste moment kan u, als u er een gewoonte van maakt, veel meer benzine kosten dan een gelijkmatiger rijstijl." 2p 24 Leg uit dat het doel van dit bericht paste bij de actuele situatie in 1973.$$, array[]::uuid[]),
  ('8e39d842-2714-44a1-9e68-075c30305aa5', '03a02853-4a73-4e4c-bf3b-854db1b33ec3', 25,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1978-2008)"}, {"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["punk", "provo's", "jongerencultuur", "protestbeweging", "overeenkomst en verschil", "gezag"]'::jsonb,
   $$Met een punklied uit 1983 een overeenkomst en een verschil aantonen tussen de standpunten van provo's en de punkbeweging.$$,
   $$geschiedenis-havo-2021-i-nederland-1948-2008-vraag25.png$$, $$Gebruik bron 1. Een conclusie: Met deze bron kun je een overeenkomst en een verschil aantonen tussen de standpunten van de provo''s en die van de punkbeweging. 4p 25 Ondersteun deze conclusie door, telkens met een passende verwijzing naar de bron:
− een standpunt van de punkbeweging aan te geven dat overeenkomt met dat van de provo''s en
− een standpunt van de punkbeweging aan te geven dat verschilt van dat van de provo''s.
⚠️ CONTROLEREN: in de PDF staat "Gebruik bron 1.", bedoeld is bron 12 (het punklied).$$, array['b936413c-bb42-4d4b-99a2-9361ff344980']::uuid[]),
  ('ebf2fdaa-3517-4c10-9a14-cfd150c5044d', 'c42f51e6-88e1-4883-959c-f5f58b3f67f0', 26,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1978-2008)"}]'::jsonb,
   '["Europese integratie", "Europese Grondwet", "referendum 2005", "euroscepsis", "spotprent", "Balkenende"]'::jsonb,
   $$Met een cartoon uit 2005 uitleggen welke oorzaak van problemen bij de Europese samenwerking wordt weergegeven.$$,
   $$geschiedenis-havo-2021-i-computer-en-televisie-vraag26.png$$, $$Gebruik bron 13. Carlo Schneider geeft een oorzaak weer van problemen bij de Europese samenwerking in de eenentwintigste eeuw. 2p 26 Leg uit welke oorzaak dat is, waarbij je je antwoord ondersteunt met een passende verwijzing naar de bron.$$, array['51f1fc56-f3b6-499d-8436-116e48c4f682']::uuid[]),
  ('155c22d4-a984-4ba0-9e29-0babae624230', 'c42f51e6-88e1-4883-959c-f5f58b3f67f0', 27,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1978-2008)"}]'::jsonb,
